#pragma once
#include "kstationProgramStateTask.h"
#include "kstationControllerProgramCopyTask.h"
#include <optional>
namespace kstation {
class ControllerProgramLoadTask final {
 using L=ProgramLoadTask;using LS=L::Stage;using A=ProgramAddressTask;using AS=A::Stage;using I=ProgramIndexTask;using IS=I::Stage;using O=ProgramModeTask;using OS=O::Stage;using C=ControllerProgramCopyTask;
public:enum class Service:uint8_t{None,DspWrite,RefreshPanel,InitializeVoice,ReleaseVoices};struct Request{Service service=Service::None;uint16_t address=0;uint32_t word=0;uint8_t part=0;};bool complete()const{return load_.complete()&&!address_&&!index_&&!copy_&&!mode_;}
 Request request()const{if(copy_){auto r=copy_->request();return {r.service==C::Service::DspWrite?Service::DspWrite:r.service==C::Service::RefreshPanel?Service::RefreshPanel:r.service==C::Service::InitializeVoice?Service::InitializeVoice:Service::None,r.address,r.word,r.part};}if(load_.awaiting()&&load_.stage()==LS::ClearPending)return {Service::ReleaseVoices,0,0,0};return {};}
 bool resume(Service s){if(s==Service::None||request().service!=s)return false;if(copy_)return copy_->resume(s==Service::DspWrite?C::Service::DspWrite:s==Service::RefreshPanel?C::Service::RefreshPanel:C::Service::InitializeVoice);return load_.resumeChild();}
 bool stackWrites()const{if(mode_)return mode_->stage()==OS::Retain;if(copy_)return copy_->stackWrites();if(index_)return index_->stage()==IS::Retain;if(address_){auto s=address_->stage();return s==AS::ReadIndex||s==AS::Retain;}auto s=load_.stage();return s==LS::ResolveAddress||s==LS::Copy||s==LS::ModeLatch||s==LS::ReleaseVoices;}
 unsigned nextClocks(int previous=-1)const{if(request().service!=Service::None)return 0;if(copy_)return copy_->nextClocks(previous);FlashCredits c;c.read=3;c.write=3;if(mode_){if(mode_->stage()==OS::Publish)c.write=bus(0xd0ee,previous);return mode_->nextClocks(c);}if(index_){auto a=index_->source()+(index_->stage()==IS::ReadProgram?1:0);c.read=bus(a,-1);return index_->nextClocks(c);}if(address_)return address_->nextClocks(c);if(load_.stage()==LS::PublishPending)c.write=bus(0xcc02,previous);return load_.nextClocks(c);}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;if(copy_){auto used=copy_->advanceBefore(cost,read,write,previous);if(copy_->complete()){copy_.reset();load_.resumeChild();}return used;}FlashCredits c;c.read=3;c.write=3;if(mode_){if(mode_->stage()==OS::Publish)c.write=bus(0xd0ee,previous);auto used=mode_->advanceBefore(cost,c,[&](){return read(0xbb23,1,cost);},[&](uint8_t v){write(0xd0ee,v,1,cost);});if(mode_->complete()){mode_.reset();load_.resumeChild();}return used;}if(index_){auto a=index_->source()+(index_->stage()==IS::ReadProgram?1:0);c.read=bus(a,-1);auto used=index_->advanceBefore(cost,c,[&](bool program){return read(index_->source()+(program?1:0),1,program?cost:cost-2);});if(index_->complete()){auto value=index_->result();index_.reset();address_->resumeChild(value);}return used;}if(address_){auto used=address_->advanceBefore(cost,c,[&](){return read(0xcd77,1,cost);});if(address_->awaiting()&&!index_)index_.emplace(0xcd82);if(address_->complete()){source_=address_->result();address_.reset();load_.resumeChild();}return used;}if(load_.stage()==LS::PublishPending)c.write=bus(0xcc02,previous);auto used=load_.advanceBefore(cost,c,[&](uint8_t v){write(0xcc02,v,1,cost);});if(load_.awaiting()){auto s=load_.stage();if(s==LS::Copy)address_.emplace();else if(s==LS::ModeLatch)copy_.emplace(source_);else if(s==LS::ClearVoice)mode_.emplace();}return used;}
private:static unsigned bus(uint32_t a,int p){a&=0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0))return (p&1)||a!=uint32_t(p|1)?(a<0x400000?3:1):0;return a>=0xffffa0?1:3;}L load_{};uint32_t source_=0;std::optional<A>address_{};std::optional<I>index_{};std::optional<C>copy_{};std::optional<O>mode_{};
};
}
